tests.code:
const nums = [5];
const out = addTen(nums);
assert.deepEqual(nums, [5]);
assert.deepEqual(out, [15]);

answer:
function addTen(numbers) {
  let result = [];
  result = numbers.map((n) => n + 10);
  return result;
}
